import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.Route;

@Route(value = "", layout = MainLayout.class)
public class ItemsView extends VerticalLayout {

    private final UnorderedList list = new UnorderedList();
    private final Span countSpan = new Span("Items: 0");
    private int count = 0;

    public ItemsView() {
        H1 heading = new H1("Items");

        TextField itemField = new TextField("Item");

        Button addButton = new Button("Add", event -> {
            String value = itemField.getValue();
            if (value == null || value.isBlank()) {
                itemField.setInvalid(true);
                return;
            }
            itemField.setInvalid(false);
            list.add(new ListItem(value));
            count++;
            countSpan.setText("Items: " + count);
            itemField.clear();
        });

        Button clearButton = new Button("Clear", event -> {
            list.removeAll();
            count = 0;
            countSpan.setText("Items: 0");
        });

        add(heading, itemField, addButton, clearButton, list, countSpan);
    }
}
